import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    os.makedirs(dst_folder, exist_ok=True)
    failed_files = []
    processes = []
    for file_path in glob(os.path.join(src_folder, '*')):
        if os.path.isfile(file_path):
            proc = subprocess.Popen(['gzip', file_path])
            processes.append((os.path.basename(file_path), file_path, proc))
    for filename, file_path, proc in processes:
        proc.wait()
        if proc.returncode != 0:
            failed_files.append(filename)
        else:
            gz_path = file_path + '.gz'
            try:
                shutil.move(gz_path, os.path.join(dst_folder, filename + '.gz'))
            except Exception:
                failed_files.append(filename)
    success = len(failed_files) == 0
    message = "All files compressed and moved successfully." if success else "Some files failed to compress or move."
    return {'success': success, 'message': message, 'failed_files': failed_files}

